import frappe

SCRIPT = "(function(){\n    'use strict';\n    var btnDl  = root_element.getElementById('vp-download');\n    var tbody  = root_element.getElementById('vp-tbody');\n    var empty  = root_element.getElementById('vp-empty');\n    var table  = root_element.getElementById('vp-table');\n    var lblUpd = root_element.getElementById('vp-updated');\n\n    if (!tbody) return;\n\n    function _dmy(s){ return s ? s.split('-').reverse().join('-') : ''; }\n    function _inr(n){ return '₹'+(parseFloat(n)||0).toLocaleString('en-IN',{minimumFractionDigits:0,maximumFractionDigits:0}); }\n    function _esc(s){ return frappe.utils.escape_html(s||''); }\n\n    // Last values broadcast by the shared \"TMS Filter Bar\" block. Kept separate from\n    // what was actually sent so that un-ticking Show All can restore them.\n    var _filter = { from_date:'', to_date:'', company:'', branch:'' };\n    var _showAll = false;\n    var _data = [];\n\n    function renderRows(rows){\n        _data = (rows || []).slice().sort(function(a, b){\n    return (a.vendor || '').localeCompare(b.vendor || '', undefined, { numeric: true, sensitivity: 'base' });\n});\n        tbody.innerHTML = '';\n        if (!_data.length){\n            table.style.display = 'none';\n            empty.style.display = '';\n            return;\n        }\n        table.style.display = '';\n        empty.style.display = 'none';\n        _data.forEach(function(r,i){\n            var tr = document.createElement('tr');\n            tr.innerHTML =\n                '<td style=\"color:var(--text-muted);font-size:12px;\">'+(i+1)+'</td>'+\n                '<td><a class=\"vp-vendor-link\" href=\"#\" data-vendor=\"'+_esc(r.vendor)+'\">'+_esc(r.vendor)+'</a></td>'+\n                '<td>'+_esc(r.vendor_type||'')+'</td>'+\n                '<td style=\"text-align:right;\" class=\"vp-amt\">'+_inr(r.total_freight)+'</td>'+\n                '<td style=\"text-align:right;\" class=\"vp-amt\">'+_inr(r.paid_amount)+'</td>'+\n                '<td style=\"text-align:right;\"><span class=\"vp-balance\">'+_inr(r.balance)+'</span></td>'+\n                '<td style=\"text-align:center;\">'+_dmy(r.oldest_trip_date ? String(r.oldest_trip_date).slice(0,10) : '')+'</td>';\n            tr.querySelector('.vp-vendor-link').addEventListener('click', function(e){\n                e.preventDefault();\n                frappe.set_route('List','Trip',{'vendor': this.dataset.vendor});\n            });\n            tbody.appendChild(tr);\n        });\n        if (lblUpd) lblUpd.textContent = 'Updated '+new Date().toLocaleTimeString();\n    }\n\n    function fetchData(fromDate, toDate, company, branch){\n        frappe.call({\n            method: 'logicore.logicore.api.get_vendor_pending_summary',\n            args: {\n                from_date: fromDate || '',\n                to_date:   toDate   || '',\n                company:   company  || '',\n                branch:    branch   || ''\n            },\n            callback: function(r){\n                renderRows(r && r.message ? r.message : []);\n            },\n            error: function(){\n                renderRows([]);\n            }\n        });\n    }\n\n    function applyFilter(){\n        if (_showAll) {\n            fetchData('', '', '', '');\n        } else {\n            fetchData(_filter.from_date, _filter.to_date, _filter.company, _filter.branch);\n        }\n    }\n\n    btnDl.addEventListener('click', function(){\n        if (!_data.length) return;\n        var header = ['#','Vendor Name','Type','Total Freight','Paid Amount','Balance Amount','Older Bill/Trip Date'];\n        var lines  = [header.join(',')];\n        _data.forEach(function(r,i){\n            lines.push([\n                i+1,\n                '\"'+(r.vendor||'').replace(/\"/g,'\"\"')+'\"',\n                '\"'+(r.vendor_type||'').replace(/\"/g,'\"\"')+'\"',\n                parseFloat(r.total_freight)||0,\n                parseFloat(r.paid_amount)||0,\n                parseFloat(r.balance)||0,\n                r.oldest_trip_date ? String(r.oldest_trip_date).slice(0,10) : ''\n            ].join(','));\n        });\n        var blob = new Blob([lines.join('\\n')], {type:'text/csv'});\n        var url  = URL.createObjectURL(blob);\n        var a    = document.createElement('a');\n        a.href = url;\n        a.download = _showAll\n            ? 'vendor_pending_all.csv'\n            : 'vendor_pending_'+_filter.from_date+'_to_'+_filter.to_date+'.csv';\n        document.body.appendChild(a);\n        a.click();\n        document.body.removeChild(a);\n        URL.revokeObjectURL(url);\n    });\n\n    var cbShowAll = root_element.getElementById('tvp-show-all');\n    if (cbShowAll) {\n        cbShowAll.checked = _showAll;\n        cbShowAll.addEventListener('change', function() {\n            _showAll = this.checked;\n            applyFilter();\n        });\n    }\n\n    window.addEventListener('tms-filter-changed', function(e) {\n        var d = (e && e.detail) || {};\n        _filter.from_date = d.from_date || '';\n        _filter.to_date   = d.to_date   || '';\n        _filter.company   = d.company   || '';\n        _filter.branch    = d.branch    || '';\n        // A new filter selection always wins over Show All — untick it so the\n        // table follows the shared filter again.\n        _showAll = false;\n        if (cbShowAll) cbShowAll.checked = false;\n        applyFilter();\n    });\n}());"


def run():
	doc = frappe.get_doc("Custom HTML Block", 'TMS Vendor Pending')
	doc.script = SCRIPT
	doc.save(ignore_permissions=True)
	frappe.db.commit()
	print('Updated TMS Vendor Pending block')
